const update = $json;
const callback = update.callback_query ?? null;
const msg = callback?.message ?? update.message ?? update;
const from = callback?.from ?? msg.from ?? {};

const chatId = String(msg.chat?.id ?? msg.chat_id ?? from.id ?? '');
const externalUserId = String(from.id ?? '');
const username = from.username ?? '';
const firstName = from.first_name ?? '';
const lastName = from.last_name ?? '';
const messageId = String(msg.message_id ?? msg.id ?? '');
const text = String(msg.text ?? msg.caption ?? '').trim();
const callbackData = String(callback?.data ?? '').trim();

const document = msg.document ?? null;
const photo = msg.photo ?? null;
const voice = msg.voice ?? null;
const audio = msg.audio ?? null;
const videoNote = msg.video_note ?? null;
const video = msg.video ?? null;
const sticker = msg.sticker ?? null;
const animation = msg.animation ?? null;
const contact = msg.contact ?? null;
const location = msg.location ?? null;

let fileId = document?.file_id ?? null;
let fileName = document?.file_name ?? null;
let mimeType = document?.mime_type ?? null;

if (!fileId && Array.isArray(photo) && photo.length > 0) {
  const bestPhoto = photo[photo.length - 1];
  fileId = bestPhoto.file_id ?? null;
  fileName = `photo_${messageId}.jpg`;
  mimeType = 'image/jpeg';
}

const SUPPORTED_MIME = new Set([
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'text/csv', 'application/csv', 'application/vnd.ms-excel',
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/msword',
  'text/plain',
  'image/jpeg', 'image/png',
]);

let messageType = 'unknown';
if (fileId && SUPPORTED_MIME.has(mimeType)) messageType = 'supported_file';
else if (fileId && document) messageType = 'unsupported_file';
else if (voice || audio) messageType = 'voice';
else if (sticker) messageType = 'sticker';
else if (animation) messageType = 'animation';
else if (videoNote || video) messageType = 'video';
else if (contact) messageType = 'contact';
else if (location) messageType = 'location';
else if (text) messageType = 'text';

let route = 'unknown';
const startMatch = /^\/start\s+(\S+)/.exec(text);
const startPayload = startMatch ? startMatch[1] : '';
if (startPayload) route = 'deep_link_register';
else if (callbackData === 'register_supplier' || callbackData === 'start_registration') route = 'callback_register_supplier';
else if (callbackData === 'cancel_registration') route = 'callback_cancel_registration';
else if (callbackData === 'process_pending_upload') route = 'callback_process_pending_upload';
else if (callbackData === 'upload_new_price' || callbackData === 'update_price_upload') route = 'callback_upload_new_price';
else if (callbackData === 'confirm_upload') route = 'callback_confirm_upload';
else if (callbackData === 'reject_upload') route = 'callback_reject_upload';
else if (callbackData === 'show_products') route = 'show_products';
else if (callbackData === 'contact_manager' || callbackData === 'help') route = 'contact_manager';
else if (callbackData === 'supplier_main_menu' || callbackData === 'main_menu') route = 'supplier_main_menu';
else if (callbackData === 'open_cabinet') route = 'open_cabinet';
else if (messageType === 'supported_file') route = 'file_upload';
else if (messageType === 'unsupported_file') route = 'unsupported_format';
else if (messageType === 'voice') route = 'voice_message';
else if (['sticker', 'animation', 'video', 'contact', 'location'].includes(messageType)) route = 'unsupported_message';
else if (/^(измени|обнови|поменяй|поставь)\b/i.test(text) && /цен/i.test(text)) route = 'update_price_command';
else if (/^(покажи|список|товары|каталог|мои товары|мой прайс)\b/i.test(text)) route = 'show_products';
else if (/^(меню|старт|start|menu|help|помощь|\/?start|\/?help|\/?menu)$/i.test(text)) route = 'supplier_main_menu';
else if (/^(привет|здравствуй|добрый|доброе|добрый день|добрый вечер|доброе утро|хай|hi|hello|йо)\b/i.test(text)) route = 'greeting';
else if (/^(спасибо|благодар|пасиб|thx|thanks|ок|ладно|понял|хорошо|отлично|супер|круто|класс|ура)\b/i.test(text)) route = 'thanks';
else if (/\?\s*$/.test(text) || /^(как|что|где|когда|зачем|почему|можно|а можно|скажи|подскажи|расскажи)\b/i.test(text)) route = 'question';
else if (/^(загрузи|отправ|прайс|файл|excel|эксель|xlsx|csv|pdf)\b/i.test(text)) route = 'wants_upload';
// text uploads disabled — all text goes through NLP or unknown_text
else if (text) route = 'unknown_text';

return {
  json: {
    source_channel: 'telegram',
    platform: 'telegram',
    chat_id: chatId,
    external_user_id: externalUserId,
    telegram_user_id: externalUserId,
    username,
    first_name: firstName,
    last_name: lastName,
    message_id: messageId,
    text,
    callback_data: callbackData,
    callback_query_id: callback?.id ?? '',
    is_callback_query: Boolean(callback?.id),
    has_file: Boolean(fileId),
    file_id: fileId,
    file_name: fileName,
    mime_type: mimeType,
    message_type: messageType,
    route,
    start_payload: startPayload,
    n8n_execution_id: typeof $execution !== 'undefined' ? String($execution.id) : '',
    received_at: new Date().toISOString(),
  },
};

let resolved = {};
try { resolved = $('Restore Pending Upload Context').first().json; } catch (error) {}
if (!resolved?.supplier_id) {
  try {
    const registered = $('Register Supplier Binding').first().json;
    resolved = {
      ...resolved,
      ...registered,
      supplier_id: registered["binding"]?.["supplier_id"],
      supplier_name: registered["binding"]?.["supplier_name"],
    };
  } catch (error) {}
}
if (!resolved?.supplier_id) {
  const bound = $('Resolve Supplier Binding').first().json;
  resolved = {
    ...resolved,
    ...bound,
    supplier_id: bound["binding"]?.["supplier_id"],
    supplier_name: bound["binding"]?.["supplier_name"],
  };
}
const context = {
  ...resolved,
  supplier_id: resolved.supplier_id ?? resolved["binding"]?.["supplier_id"],
  supplier_name: resolved.supplier_name ?? resolved["binding"]?.["supplier_name"],
  pending_action_id: resolved.pending_action_id ?? resolved.pending_action?.id ?? null,
};
const incoming = $('Normalize Incoming Telegram Message').first().json;
const upload = $('Create Upload - File').first().json;

const CHUNK_SIZE = 10;
const MAX_CELL_LENGTH = 240;
const MAX_COLUMNS = 14;
const SYSTEM_KEYS = new Set([
  'id', 'status', 'supplier_id', 'source_channel', 'source_file_name',
  'raw_payload', 'ai_payload', 'processed_at', 'created_at', 'updated_at',
]);

function cleanValue(value, maxLength = MAX_CELL_LENGTH) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return JSON.stringify(value).replace(/\s+/g, ' ').trim().slice(0, maxLength);
  return String(value).replace(/\s+/g, ' ').trim().slice(0, maxLength);
}

function looksLikeUploadResponse(json) {
  if (!json || typeof json !== 'object') return false;
  if (upload?.id && json.id === upload.id) return true;
  const keys = Object.keys(json);
  const systemKeyCount = keys.filter((key) => SYSTEM_KEYS.has(key)).length;
  return Boolean(json.id && json.status && json.source_channel && systemKeyCount >= 3);
}

function getSpreadsheetItems() {
  try {
    const rows = $('Read Spreadsheet Rows').all();
    if (Array.isArray(rows) && rows.length > 0) return rows;
  } catch (error) {}
  return $input.all().filter((item) => !looksLikeUploadResponse(item.json));
}

const spreadsheetItems = getSpreadsheetItems();
const rows = [];
for (const item of spreadsheetItems) {
  const source = item.json ?? {};
  if (looksLikeUploadResponse(source)) continue;

  const clean = {};
  for (const [key, value] of Object.entries(source)) {
    if (key === '__rowNum__' || key === 'row_number' || key === 'rowNumber') continue;
    const normalizedKey = cleanValue(key, 80);
    const text = cleanValue(value);
    if (!normalizedKey || !text) continue;
    if (Object.keys(clean).length >= MAX_COLUMNS) break;
    clean[normalizedKey] = text;
  }
  if (Object.keys(clean).length === 0) continue;

  const sourceRowNumber = Number(source.__rowNum__ ?? source.row_number ?? source.rowNumber);
  rows.push({
    row_number: Number.isFinite(sourceRowNumber) && sourceRowNumber > 0 ? sourceRowNumber : rows.length + 1,
    cells: clean,
  });
}

if (rows.length === 0) {
  return [{
    json: {
      ...context,
      ...incoming,
      upload_id: upload.id,
      upload_status: upload.status,
      source_file_name: upload.source_file_name,
      chunk_index: 1,
      chunk_total: 1,
      chunk_start_row: null,
      chunk_end_row: null,
      rows: [],
      ai_input_text: 'Прайс не содержит распознанных строк.',
    },
  }];
}

const chunks = [];
for (let start = 0; start < rows.length; start += CHUNK_SIZE) {
  chunks.push(rows.slice(start, start + CHUNK_SIZE));
}

return chunks.map((chunkRows, index) => {
  const aiInputText = chunkRows.map((row) => {
    const cells = Object.entries(row.cells)
      .map(([key, value]) => `${key}: ${value}`)
      .join('; ');
    return `row_number=${row.row_number}; ${cells}`;
  }).join('\n');

  return {
    json: {
      ...context,
      ...incoming,
      upload_id: upload.id,
      upload_status: upload.status,
      source_file_name: upload.source_file_name,
      chunk_index: index + 1,
      chunk_total: chunks.length,
      chunk_start_row: chunkRows[0]?.row_number ?? null,
      chunk_end_row: chunkRows[chunkRows.length - 1]?.row_number ?? null,
      rows: chunkRows,
      ai_input_text: aiInputText,
    },
  };
});

const rows = Array.isArray($json.rows) ? $json.rows : [];
if (rows.length > 30) {
  throw new Error(`Chunk overflow: rows.length=${rows.length}, chunk_index=${$json.chunk_index ?? 'unknown'}`);
}
return { json: { ...$json } };

let context = {};
try { context = $('Merge Binding And State').first().json; } catch (error) {}
if (!context?.supplier_id) {
  try {
    const registered = $('Register Supplier Binding').first().json;
    context = {
      ...context,
      ...registered,
      supplier_id: registered["binding"]?.["supplier_id"] ?? null,
      supplier_name: registered["binding"]?.["supplier_name"] ?? null,
    };
  } catch (error) {}
}
const incoming = $('Normalize Incoming Telegram Message').first().json;
const upload = $('Create Upload - Text').first().json;

const CHUNK_SIZE = 30;
const MAX_LINE_LENGTH = 600;
function cleanLine(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, MAX_LINE_LENGTH);
}

const lines = String(incoming.text ?? '')
  .split(/\r?\n/)
  .map(cleanLine)
  .filter(Boolean);

const rows = lines.length > 0
  ? lines.map((line, index) => ({ row_number: index + 1, cells: { text: line } }))
  : [{ row_number: 1, cells: { text: cleanLine(incoming.text) } }];

const chunks = [];
for (let start = 0; start < rows.length; start += CHUNK_SIZE) {
  chunks.push(rows.slice(start, start + CHUNK_SIZE));
}

return chunks.map((chunkRows, index) => ({
  json: {
    ...context,
    ...incoming,
    upload_id: upload.id,
    upload_status: upload.status,
    chunk_index: index + 1,
    chunk_total: chunks.length,
    chunk_start_row: chunkRows[0]?.row_number ?? null,
    chunk_end_row: chunkRows[chunkRows.length - 1]?.row_number ?? null,
    ai_input_text: chunkRows.map((row) => `row_number=${row.row_number}; text: ${row.cells.text}`).join('\n'),
    rows: chunkRows,
  },
}));

