function stripCodeFence(value) {
  return String(value ?? '').replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
}
function pickAiText(json) {
  const value = json.ai_raw_output
    ?? json.output
    ?? json.text
    ?? json.content
    ?? json.message?.content
    ?? json.choices?.[0]?.message?.content
    ?? json.data?.choices?.[0]?.message?.content
    ?? json.body?.choices?.[0]?.message?.content
    ?? json.response?.choices?.[0]?.message?.content
    ?? '';
  return typeof value === 'object' ? JSON.stringify(value) : value;
}
function normalizeDecimal(value, fallback = null) {
  if (value === null || value === undefined || value === '') return fallback;
  const normalized = String(value).replace(/\s+/g, '').replace(',', '.').replace(/[^\d.]/g, '');
  if (!normalized) return fallback;
  const number = Number(normalized);
  if (!Number.isFinite(number)) return fallback;
  return number.toFixed(2);
}
function normalizeQty(value, fallback = null) {
  if (value === null || value === undefined || value === '') return fallback;
  const normalized = String(value).replace(/\s+/g, '').replace(',', '.').replace(/[^\d.]/g, '');
  if (!normalized) return fallback;
  const number = Number(normalized);
  if (!Number.isFinite(number)) return fallback;
  return number.toFixed(4);
}
function normalizeConfidence(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return '0.8000';
  return Math.max(0, Math.min(1, number)).toFixed(4);
}
function normalizeUnit(value) {
  const raw = String(value ?? '').trim().toLowerCase();
  const aliases = {
    'шт': 'шт', 'штука': 'шт', 'штуки': 'шт', 'pcs': 'шт', 'pc': 'шт',
    'кг': 'кг', 'kg': 'кг', 'килограмм': 'кг',
    'г': 'г', 'гр': 'г', 'gram': 'г', 'g': 'г',
    'л': 'л', 'литр': 'л', 'l': 'л',
    'мл': 'мл', 'ml': 'мл',
  };
  return aliases[raw] ?? raw;
}
function resolveCurrentChunkContext() {
  if ($json.upload_id && $json.chat_id && $json.supplier_id) return $json;
  try { return $('Validate AI Chunk').item.json; } catch (error) {}
  try { return $('Loop Over AI Chunks').item.json; } catch (error) {}
  try { return $('Prepare AI Input From Spreadsheet').item.json; } catch (error) {}
  try { return $('Prepare AI Input From Text').item.json; } catch (error) {}
  return null;
}
function resolveRowNumber(value, index, contextRows) {
  const rows = Array.isArray(contextRows) ? contextRows : [];
  const number = Number(value);
  if (Number.isFinite(number) && number > 0) {
    const absoluteMatch = rows.find((row) => Number(row.row_number) === number);
    if (absoluteMatch) return Number(absoluteMatch.row_number);
    const relativeMatch = rows[Math.trunc(number) - 1];
    if (relativeMatch?.row_number) return Number(relativeMatch.row_number);
    return Math.trunc(number);
  }
  return Number(rows[index]?.row_number ?? index + 1);
}

const context = resolveCurrentChunkContext();
if (!context?.upload_id || !context?.chat_id || !context?.supplier_id) {
  throw new Error('Cannot resolve upload_id/chat_id/supplier_id context for AI result.');
}
if ($json.error) {
  throw new Error(`AI request failed: ${JSON.stringify($json.error).slice(0, 500)}`);
}

const aiText = stripCodeFence(pickAiText($json));
if (!aiText) throw new Error(`AI response does not contain message content. Keys: ${Object.keys($json).join(', ')}`);

let parsed;
try {
  parsed = JSON.parse(aiText);
} catch (error) {
  throw new Error(`AI вернул невалидный JSON: ${error.message}. Raw: ${aiText.slice(0, 500)}`);
}
const products = Array.isArray(parsed.products) ? parsed.products : [];
const backendProducts = products.map((product, index) => {
  const warnings = Array.isArray(product.warnings) ? product.warnings.map(String) : [];
  const packageValue = String(product.package ?? product.package_info ?? '').trim();
  return {
    row_number: resolveRowNumber(product.row_number, index, context.rows),
    raw_name: String(product.raw_name ?? product.name ?? '').trim(),
    normalized_name: String(product.normalized_name ?? '').trim(),
    supplier_sku: product.supplier_sku ? String(product.supplier_sku).trim() : null,
    price: normalizeDecimal(product.price),
    currency: product.currency ? String(product.currency).trim() : 'RUB',
    unit_code: normalizeUnit(product.unit_code ?? product.unit ?? ''),
    package_info: packageValue || null,
    brand: product.brand ? String(product.brand).trim() : null,
    volume: product.volume ? String(product.volume).trim() : null,
    volume_unit: product.volume_unit ? String(product.volume_unit).trim() : null,
    weight: product.weight ? String(product.weight).trim() : null,
    weight_unit: product.weight_unit ? String(product.weight_unit).trim() : null,
    min_order_qty: normalizeQty(product.min_order_qty, null),
    multiplicity: normalizeQty(product.multiplicity, null),
    category_path: Array.isArray(product.category_path) ? product.category_path.map(String) : [],
    comment: product.comment ? String(product.comment).trim() : null,
    availability_status: product.availability_status ? String(product.availability_status).trim() : 'available',
    confidence: normalizeConfidence(product.confidence),
    warnings,
  };
});
return {
  json: {
    chat_id: context.chat_id,
    supplier_id: context.supplier_id,
    supplier_name: context.supplier_name,
    upload_id: context.upload_id,
    chunk_index: context.chunk_index ?? 1,
    chunk_total: context.chunk_total ?? 1,
    chunk_start_row: context.chunk_start_row ?? null,
    chunk_end_row: context.chunk_end_row ?? null,
    rows: context.rows ?? [],
    ai_input_text: context.ai_input_text,
    ai_payload: {
      schema_version: 'supplier_price_ai.v1',
      supplier_id: context.supplier_id,
      upload_id: context.upload_id,
      source_channel: context.source_channel,
      processing_version: String(parsed.processing_version ?? `n8n-demo-2026-06-18-chunk-${context.chunk_index ?? 1}`),
      supplier_name: String(parsed.supplier_name ?? context.supplier_name),
      products: backendProducts,
    },
  },
};

let apply = null;
try { apply = $('Aggregate AI Apply Results').first().json; } catch(e) {}
if (!apply || !apply.items_total) {
  try { apply = $('Fetch Upload Stats').first().json; } catch(e) {}
}
if (!apply || !apply.items_total) {
  try { apply = $('Get Confirmed Upload From State').first().json; } catch(e) {}
}
if (!apply) { apply = $json; }

const total = Number(apply.items_total ?? 0);
const created = Number(apply.products_created ?? 0);
const updated = Number(apply.products_updated ?? 0);
const prices = Number(apply.prices_created ?? 0);
const needsReview = Number(apply.needs_review ?? 0);
const chatId = apply.chat_id ?? $('Normalize Incoming Telegram Message').first().json.chat_id;
const supplierId = apply.supplier_id ?? '';

const lines = [
  'Прайс загружен и подтверждён! ✅',
];

if (total > 0) {
  lines.push('', `📊 Всего позиций: ${total}`, `🆕 Новых товаров: ${created}`, `🔄 Обновлено: ${updated}`, `💰 Новых цен: ${prices}`);
  if (needsReview > 0) lines.push(`⚠️ Требуют проверки: ${needsReview}`);
}

if (supplierId) {
  lines.push('', `📋 Ваши товары: https://avtosnab.testant.online/supplier/${supplierId}/`);
}

return { json: { chat_id: chatId, message_text: lines.join('\n') } };

const rows = Array.isArray($json.results) ? $json.results : [];
const lines = ['📋 Ваши товары:'];
if (rows.length === 0) {
  lines.push('', 'Пока товаров нет. Загрузите прайс — и они появятся здесь.');
} else {
  lines.push('');
  for (const row of rows.slice(0, 20)) {
    const name = row.supplier_normalized_name || row.supplier_raw_name || '—';
    const price = row.current_price?.price ?? row.price ?? '';
    const currency = row.current_price?.currency ?? 'руб';
    const unit = row.unit?.code ?? row.unit ?? '';
    lines.push(`• ${name}: ${price} ${currency}/${unit}`.trim());
  }
  if (rows.length > 20) lines.push(`\n...и ещё ${rows.length - 20}`);
}
return { json: { chat_id: $('Normalize Incoming Telegram Message').first().json.chat_id, message_text: lines.join('\n') } };

const incoming = $('Normalize Incoming Telegram Message').first().json;
const context = $json;
const text = String(incoming.text ?? '').trim();
const priceMatch = text.match(/(?:на|=)?\s*(\d+[\d\s]*(?:[,.]\d+)?)\s*(?:руб|р|₽)?\s*$/i);
if (!priceMatch) throw new Error('Не удалось выделить цену из команды.');
const price = Number(priceMatch[1].replace(/\s+/g, '').replace(',', '.'));
if (!Number.isFinite(price) || price <= 0) throw new Error('Цена должна быть положительным числом.');
let productQuery = text.replace(/^(измени|обнови|поменяй|поставь)\s+/i, '').replace(/цену\s+(на\s+)?/i, '').replace(/\s+на\s+\d+[\d\s]*(?:[,.]\d+)?\s*(?:руб|р|₽)?\s*$/i, '').trim();
if (!productQuery) throw new Error('Не удалось выделить товар из команды.');
return {
  json: {
    chat_id: incoming.chat_id,
    supplier_id: context.supplier_id,
    supplier_name: context.supplier_name,
    product_query: productQuery,
    price: price.toFixed(2),
    currency: 'RUB'
  }
};

const parsed = $('Parse Update Price Command').first().json;
const results = Array.isArray($json.results) ? $json.results : [];
if (results.length !== 1) {
  const lines = results.length === 0
    ? ['Не нашёл такой товар. Попробуйте уточнить название.']
    : ['Нашёл несколько похожих товаров. Уточните, какой именно:', ...results.map((row, i) => `${i + 1}. ${row.supplier_normalized_name || row.supplier_raw_name}`)];
